import {resolveDirectionChoice} from './direction-model-e14b41d62339.mjs';
import {orderedLabels,positionItem,shadeColor} from './catalog-order-e14b41d62339.mjs';
import * as D from './domain-e14b41d62339.mjs';
import {investmentKind,supplementDefaults} from './catalog-e14b41d62339.mjs';
import {effectiveActivity,emptyPolicy} from './activity-policy-e14b41d62339.mjs';
export function createCatalog({getState,openModal,closeModal,save,toast,entityReplace,configFields,readConfig,e,tasks}){
 let chosenGroup=null,navigation=null;
 const destination=(state,a)=>{const p=effectiveActivity(state,a);return p.mainSkillId?(state.skills.find(s=>s.id===p.mainSkillId)?.name??'培养项')+' · '+(a.growthMode==='inherit'?'沿用类别':'自定'):'仅记录时间';};
 function choose(groupId=null){if(navigation)return navigation.choose(groupId);chosenGroup=groupId;const state=getState(),group=state.activityGroups.find(g=>g.id===groupId);openModal(group?group.name:state.running?'切换活动':'此刻，想记录什么？',group?
  '<button type="button" class="text-button" data-action="catalog-groups">‹ 返回类别</button><div class="choose-grid">'+state.activities.filter(a=>a.groupId===group.id&&!a.archived).map(a=>'<button type="button" class="choose-option" data-action="quick-start" data-id="'+e(a.id)+'"><span class="color-dot" style="background:'+e(a.color)+'"></span><span>'+e(a.name)+'<small>'+e(destination(state,a))+'</small></span>'+(state.running?.activityId===a.id?'<span class="tag">当前</span>':'<b>开始 ›</b>')+'</button>').join('')+'</div><button type="button" class="secondary" data-action="catalog-create" data-id="'+e(group.id)+'">＋ 在这里新建</button><button type="button" class="text-button" data-action="edit-group" data-id="'+e(group.id)+'">类别培养设置</button>':
  '<div class="choose-grid">'+state.activityGroups.filter(g=>!g.archived).sort((a,b)=>a.order-b.order).map(g=>'<button type="button" class="choose-option" data-action="catalog-group" data-id="'+e(g.id)+'"><span>'+e(g.name)+'<small>'+state.activities.filter(a=>a.groupId===g.id&&!a.archived).length+' 项活动</small></span><b>›</b></button>').join('')+'</div>',{footer:state.running?'选定下一项才接力，返回不会改变计时。':'进入类别后，选择明确的活动开始。'});}
 async function edit(id=null,{groupId=chosenGroup,onReturn=null,allowStart=true}={}){
  const state=getState(),original=state.activities.find(a=>a.id===id),group=state.activityGroups.find(g=>g.id===(original?.groupId??groupId))??state.activityGroups[0],record=original??{id:D.uid(),name:'',groupId:group.id,category:group.name,color:'#648a73',favorite:true,mainline:false,mainSkillId:null,relatedSkillIds:[],growthMode:'inherit',archived:false,phoneMode:'parallel'};
  await tasks.open({id:id?'activity:'+id:'activity:new:'+group.id,kind:'activity',title:original?'活动设置':'在'+group.name+'下新建',original,initial:{...record,favorite:record.favorite?['on']:[],mainline:record.mainline?['on']:[],archived:record.archived?['on']:[],colorShade:record.colorShade??'auto',position:original?orderedLabels(state,group.id).findIndex(a=>a.id===id)+1:orderedLabels(state,group.id).length+1},extra:{entityId:record.id},onReturn:onReturn??(()=>choose(group.id)),
   body:()=>'<label>活动名称<input name="name" maxlength="60" required autofocus></label><label>培养去向<select name="growthMode"><option value="inherit">沿用类别</option><option value="override">本活动自定</option><option value="none">仅记录时间</option></select></label><section data-custom-policy>'+configFields(record)+'</section><details class="form-details"><summary>类别、常用与其他设置</summary><label>所属类别<select name="groupId">'+state.activityGroups.map(g=>'<option value="'+e(g.id)+'">'+e(g.name)+'</option>').join('')+'</select></label><label>标签色阶<select name="colorShade"><option value="auto">按次序自动分色</option>'+[0,.08,.16,.24,.32,.4].map((v,i)=>'<option value="'+v+'">'+(i?'浅 '+i+' 阶':'分类原色')+'</option>').join('')+'</select></label><label>标签次序<select name="position"></select></label><label class="check"><input type="checkbox" name="favorite">放在常用</label><label class="check"><input type="checkbox" name="mainline">主线投入</label><label class="check"><input type="checkbox" name="archived">归档收起，历史保留</label><label>手机使用约定<select name="phoneMode"><option value="parallel">并行记录</option><option value="focus">专注：选定App切换</option></select></label></details>'+(!original&&allowStart?'<label class="check"><input type="checkbox" name="startAfter">保存后立即开始／接力</label>':'')+'<p class="quiet-note">只影响之后新开始的记录，历史与当前运行段保留原归属。</p>',
   bind(form,draft){const sync=()=>form.querySelector('[data-custom-policy]').hidden=form.elements.growthMode.value!=='override';form.elements.growthMode.onchange=sync;sync();const order=()=>{const target=form.elements.groupId.value,items=orderedLabels(state,target).filter(a=>a.id!==id),prior=form.elements.position.value;form.elements.position.innerHTML=Array.from({length:items.length+1},(_,i)=>'<option value="'+(i+1)+'">第 '+(i+1)+' 位</option>').join('');form.elements.position.value=String(Math.min(items.length+1,Number(prior)||Number(draft.payload.values.position)||items.length+1));};order();form.elements.groupId.onchange=order;},
   onSave:async(f,{commit,original:old,payload})=>{const g=getState().activityGroups.find(g=>g.id===f.get('groupId'));if(!g)throw Error('所属类别已变化');const mode=f.get('growthMode'),policy=mode==='override'?readConfig(f,old):emptyPolicy(),next={...(old??record),id:payload.entityId,name:String(f.get('name')).trim(),groupId:g.id,category:g.name,color:shadeColor(g.color,f.get('colorShade')==='auto'?0:Number(f.get('colorShade'))),colorShade:f.get('colorShade')==='auto'?undefined:Number(f.get('colorShade')),investmentKind:old?.investmentKind??investmentKind(g.name),favorite:f.has('favorite'),mainline:f.has('mainline'),archived:f.has('archived'),phoneMode:f.get('phoneMode'),growthMode:mode,explicitlyExcluded:mode==='none',...policy};
    await commit(s=>{next.mainSkillId=resolveDirectionChoice(s,next.mainSkillId);s=entityReplace(s,'activities',old,next);positionItem(orderedLabels(s,g.id),next.id,f.get('position'));if(allowStart&&f.has('startAfter')){if(next.archived)throw Error('归档的活动不能开始');s=D.switchTimer(s,next.id,Date.now());}return s;});toast('活动已保存');}
  });
 }
 async function editGroup(id,{onReturn=null}={}){const group=getState().activityGroups.find(g=>g.id===id);if(!group)return;await tasks.open({id:'group:'+id,kind:'activity',title:group.name+'的默认培养',original:group,initial:group.growthPolicy,body:()=>configFields(group.growthPolicy)+'<p class="quiet-note">只有选择沿用类别的活动会用于后续新记录；原有历史不变。</p>',onReturn:onReturn??(()=>choose(id)),onSave:async(f,{commit,original})=>{const p=readConfig(f,original.growthPolicy);await commit(s=>{const index=s.activityGroups.findIndex(g=>g.id===id);if(JSON.stringify(s.activityGroups[index])!==JSON.stringify(original))throw Error('类别配置已变化，草稿保留');p.mainSkillId=resolveDirectionChoice(s,p.mainSkillId);s.activityGroups[index]={...original,growthPolicy:p,version:original.version+1};return s;});}});}
 function manage(){if(navigation)return navigation.manage();const state=getState();openModal('活动与培养去向',state.activityGroups.map(g=>'<details class="form-details"><summary>'+e(g.name)+'</summary><button type="button" class="text-button" data-action="edit-group" data-id="'+e(g.id)+'">类别默认培养</button>'+state.activities.filter(a=>a.groupId===g.id).map(a=>'<div class="section-title"><span>'+e(a.name)+(a.archived?' · 已归档':'')+'<small> · '+e(destination(state,a))+'</small></span><button type="button" class="secondary" data-action="edit-activity" data-id="'+e(a.id)+'">设置</button></div>').join('')+'<button type="button" class="text-button" data-action="catalog-create" data-id="'+e(g.id)+'">＋ 新建活动</button></details>').join('')+'<button type="button" class="text-button" data-action="supplement-defaults">补充缺少的默认活动</button>');}
 function supplement(){const state=getState(),next=supplementDefaults(state),added=next.activities.filter(a=>!state.activities.some(x=>x.id===a.id));openModal('补充默认目录','<p>'+ (added.length?'将补充：'+added.map(a=>e(a.name)).join('、'):'没有缺少的默认活动')+'</p><p>原关联、归档状态与历史保持；同名或同ID不重复。</p>',{onSubmit:added.length?async()=>{await save(supplementDefaults);closeModal();}:null});}
 return {edit,editGroup,manage,choose,supplement,setNavigation:routes=>navigation=routes};
}
